ALTER TABLE "orders" ADD CONSTRAINT "orders_status_check" CHECK ("orders"."status" IN ('DRAFT', 'PENDING_PAYMENT', 'PAYMENT_SUBMITTED', 'PAYMENT_CONFIRMED', 'PAYMENT_REJECTED', 'PAYMENT_CONFIRMED', 'PACKING', 'SHIPPED', 'DELIVERED', 'CANCELED', 'REFUNDED'));